    { id = 4286, name = "The Good Stuff", side = "Alliance", level = 56, minLevel = 50, xp = 10763, money = 8500, giver = "Oralius", giverNpc = 9177, turnIn = "Oralius", turnInNpc = 9177, shareable = true, loot = { { item = 11468, name = "Dark Iron Fanny Pack", from = { { name = "Anvilrage Captain" }, { name = "Anvilrage Footman" } } } }, rewards = { 11883 }, objective = "Travel to Blackrock Depths and recover 20 Dark Iron Fanny Packs. Return to Oralius when you have completed this task. You assume that the Dark Iron dwarves inside Blackrock Depths carry these 'fanny pack' contraptions." },
    { id = 4322, name = "Jail Break!", side = "Alliance", level = 58, minLevel = 50, xp = 14368, money = 17500, giver = "Marshal Windsor", chainStart = 4182, chainStartName = "Dragonkin Menace", giverInside = "BRD", chainGiver = "Helendis Riverhorn", chainGiverNpc = 9562, turnIn = "Marshal Maxwell", turnInNpc = 9560, chainStep = 12, shareable = false, choice = { 12061, 12062 }, rewards = { 12065 }, chain = { 4182, 4183, 4184, 4185, 4186, 4223, 4224, 4241, 4242, 4264, 4282 }, objective = "Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed." },
    { id = 4341, name = "Kharan Mighthammer", side = "Alliance", level = 59, minLevel = 50, xp = 11845, giver = "King Magni Bronzebeard", chainStart = 3702, chainStartName = "The Smoldering Ruins of Thaurissan", giverNpc = 2784, chainGiver = "Royal Historian Archesonus", chainGiverNpc = 8879, turnIn = "Kharan Mighthammer", turnInInside = "BRD", chainStep = 3, shareable = true, chain = { 3702, 3701 }, objective = "Travel to Blackrock Depths and find Kharan Mighthammer.\n\nThe King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison." },
    { id = 4362, name = "The Fate of the Kingdom", side = "Alliance", level = 59, minLevel = 50, xp = 17407, giver = "King Magni Bronzebeard", chainStart = 3702, chainStartName = "The Smoldering Ruins of Thaurissan", giverNpc = 2784, chainGiver = "Royal Historian Archesonus", chainGiverNpc = 8879, turnIn = "Princess Moira Bronzebeard", turnInInside = "BRD", chainStep = 6, shareable = true, kills = { { name = "Emperor Dagran Thaurissan" } }, chain = { 3702, 3701, 4341, 4342, 4361 }, objective = "Return to Blackrock Depths and rescue Princess Moira Bronzebeard from the evil clutches of Emperor Dagran Thaurissan." },
    { id = 4024, name = "A Taste of Flame", level = 58, minLevel = 52, xp = 11793, money = 26500, giver = "Cyrus Therepentous", chainStart = 3441, chainStartName = "Divine Retribution", giverNpc = 9459, chainGiver = "Kalaran Windblade", chainGiverNpc = 8479, turnIn = "Cyrus Therepentous", turnInNpc = 9459, chainStep = 11, shareable = false, loot = { { item = 11230, name = "Encased Fiery Essence", from = { { name = "Bael'Gar" } } } }, choice = { 12066, 12082, 12083 }, chain = { 3441, 3442, 3443, 3452, 3453, 3454, 3462, 3463, 3481, 4022 }, objective = "Travel to Blackrock Depths and slay Bael'Gar.\n\nYou only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence.\n\nReturn the Encased Fiery Essence to Cyrus Therepentous." },
    { id = 4132, name = "Operation: Death to Angerforge", side = "Horde", level = 58, minLevel = 52, xp = 7750, money = 26500, giver = "Warlord Goretooth", chainStart = 4081, chainStartName = "KILL ON SIGHT: Dark Iron Dwarves", giverNpc = 9077, chainGiver = "WANTED", chainGiverNpc = -164867, turnIn = "Warlord Goretooth", turnInNpc = 9077, chainStep = 5, shareable = true, kills = { { name = "General Angerforge" } }, rewards = { 12059 }, chain = { 4081, 4082, 4122, 4121 }, objective = "Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete." },
    { id = 4121, name = "Precarious Predicament", side = "Horde", level = 58, minLevel = 52, xp = 7750, money = 26500, giver = "Grark Lorkrub", chainStart = 4081, chainStartName = "KILL ON SIGHT: Dark Iron Dwarves", giverNpc = 9520, chainGiver = "WANTED", chainGiverNpc = -164867, turnIn = "Lexlort", turnInNpc = 9080, chainStep = 4, shareable = false, loot = { { item = 11286, name = "Thorium Shackles", from = {  } } }, chain = { 4081, 4082, 4122 }, objective = "Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge.\n\nYou recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody.\n\nYou will also be required to hand over your Thorium Shackles to Lexlort." },
    { id = 4063, name = "The Rise of the Machines", side = "Horde", level = 58, minLevel = 52, xp = 6200, money = 26500, giver = "Lotwil Veriatus", chainStart = 4061, chainStartName = "The Rise of the Machines", giverNpc = 2921, chainGiver = "Hierophant Theodora Mulvadania", chainGiverNpc = 9079, turnIn = "Lotwil Veriatus", turnInNpc = 2921, chainStep = 3, shareable = true, named = { { name = "Warbringer Construct" } }, loot = { { item = 11268, name = "Head of Argelmach", from = { { name = "Golem Lord Argelmach" } } }, { item = 11269, name = "Intact Elemental Core", from = { { name = "Molten War Golem" }, { name = "Ragereaver Golem" } } } }, choice = { 12109, 12110, 12108, 12111 }, chain = { 4061, 4062 }, objective = "Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic." },
})

ns.Data:RegisterQuests("LBRS", {  -- Lower Blackrock Spire
    { id = 4788, name = "The Final Tablets", level = 58, minLevel = 40, xp = 7750, giver = "Prospector Ironboot", chainStart = 3520, chainStartName = "Screecher Spirits", giverNpc = 10460, chainGiver = "Yeh'kinya", chainGiverNpc = 8579, turnIn = "Prospector Ironboot", turnInNpc = 10460, chainStep = 6, shareable = true, loot = { { item = 12740, name = "Fifth Mosh'aru Tablet", from = { { name = "Fifth Mosh'aru Tablet" } } }, { item = 12741, name = "Sixth Mosh'aru Tablet", from = { { name = "Sixth Mosh'aru Tablet" } } } }, chain = { 3520, 3527, 4787, 3528, 5065 }, objective = "Bring the Fifth and Sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris." },
    { id = 5001, name = "Bijou's Belongings", side = "Alliance", level = 59, minLevel = 55, xp = 12875, giver = "Bijou", giverInside = "LBRS", turnIn = "Bijou", turnInInside = "LBRS", shareable = true, loot = { { item = 12345, name = "Bijou's Belongings", from = { { name = "Bijou's Belongings" } } } }, objective = "Find Bijou's Belongings and return them to her. Good luck!" },
    { id = 4862, name = "En-Ay-Es-Tee-Why", level = 59, minLevel = 55, xp = 12500, money = 9000, giver = "Kibler", giverNpc = 10260, turnIn = "Kibler", turnInNpc = 10260, shareable = true, loot = { { item = 12530, name = "Spire Spider Egg", from = { { name = "Spire Spider Egg" } } } }, rewards = { 12529 }, objective = "Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler.\n\nBy the sound of it, these eggs could be found near spiders." },
