    { id = 4981, name = "Operative Bijou", side = "Horde", level = 59, minLevel = 55, xp = 6400, giver = "Lexlort", giverNpc = 9080, turnIn = "Bijou", turnInInside = "LBRS", shareable = true, objective = "Travel to Blackrock Spire and find out what happened to Bijou." },
    { id = 4701, name = "Put Her Down", side = "Alliance", level = 59, minLevel = 55, xp = 12875, money = 18000, giver = "Helendis Riverhorn", giverNpc = 9562, turnIn = "Helendis Riverhorn", turnInNpc = 9562, shareable = true, kills = { { name = "Halycon" } }, choice = { 15824, 15825, 15827 }, objective = "Travel to Blackrock Spire and destroy the source of the worg menace. As you left Helendis, he shouted a name: Halycon. It is what the orcs refer to in regards to the worg." },
    { id = 4724, name = "The Pack Mistress", side = "Horde", level = 59, minLevel = 55, xp = 6400, money = 18000, giver = "Galamav the Marksman", giverNpc = 9081, turnIn = "Galamav the Marksman", turnInNpc = 9081, shareable = true, kills = { { name = "Halycon" } }, choice = { 15824, 15825, 15827 }, objective = "Slay Halycon, pack mistress of the Bloodaxe worg." },
    { id = 5089, name = "General Drakkisath's Command", side = "Alliance", level = 60, minLevel = 55, xp = 13235, startsFrom = "General Drakkisath's Command", startsFromId = 12780, turnIn = "Marshal Maxwell", turnInNpc = 9560, shareable = false, droppers = { { name = "Overlord Wyrmthalak" } }, objective = "Take General Drakkisath's Command to Marshal Maxwell in Burning Steppes." },
    { id = 4866, name = "Mother's Milk", level = 60, minLevel = 55, xp = 9950, money = 18000, giver = "Ragged John", giverNpc = 9563, turnIn = "Ragged John", turnInNpc = 9563, shareable = true, kills = { { name = "Ragged John", npc = 9563 } }, rewards = { 15873 }, objective = "In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you." },
    { id = 4867, name = "Urok Doomhowl", level = 60, minLevel = 55, xp = 19467, giver = "Warosh", giverInside = "LBRS", turnIn = "Warosh", turnInInside = "LBRS", shareable = false, loot = { { item = 12712, name = "Warosh's Mojo", from = { { name = "Urok Doomhowl" } } } }, rewards = { 15867 }, objective = "Read Warosh's Scroll.  Bring Warosh's Mojo to Warosh." },
    { id = 4903, name = "Warlord's Command", side = "Horde", level = 60, minLevel = 55, xp = 8300, money = 18000, giver = "Warlord Goretooth", chainStart = 98325, chainStartName = "Blood and Thunder", giverNpc = 9077, chainGiver = "Warlord Goretooth", chainGiverNpc = 9077, turnIn = "Warlord Goretooth", turnInNpc = 9077, chainStep = 2, shareable = false, kills = { { name = "Overlord Wyrmthalak" }, { name = "Highlord Omokk" }, { name = "War Master Voone" } }, loot = { { item = 12562, name = "Important Blackrock Documents", from = { { name = "Inconspicuous Documents" } } } }, choice = { 13958, 13959, 13961, 13962, 13963 }, chain = { 98325 }, objective = "Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished." },
