    { id = 4742, name = "Seal of Ascension", level = 60, minLevel = 57, xp = 8300, giver = "Scarshield Infiltrator", giverInside = "LBRS", turnIn = "Scarshield Infiltrator", turnInInside = "LBRS", shareable = true, loot = { { item = 12336, name = "Gemstone of Spirestone", from = { { name = "Highlord Omokk" } } }, { item = 12335, name = "Gemstone of Smolderthorn", from = { { name = "War Master Voone" } } }, { item = 12337, name = "Gemstone of Bloodaxe", from = { { name = "Overlord Wyrmthalak" } } }, { item = 12219, name = "Unadorned Seal of Ascension", from = {  } } }, objective = "Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan.\n\nThe Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak  of the Bloodaxe." },
    { id = 8966, name = "The Left Piece of Lord Valthalak's Amulet", level = 60, minLevel = 58, xp = 8300, giver = "Bodley", giverNear = "UBRS", giverWhere = "on the balcony in front of the Upper Blackrock Spire entrance", giverSee = 22115, giverSeeName = "Extra-Dimensional Ghost Revealer", turnIn = "Bodley", shareable = false, kills = { { name = "Mor Grayhoof" } }, loot = { { item = 21984, name = "Left Piece of Lord Valthalak's Amulet", from = { { name = "Mor Grayhoof" }, { name = "Isalien", inside = "DM_EAST" } } } }, bySide = { Alliance = { chainStart = 8905, chainStartName = "An Earnest Proposition", chainGiver = "Deliana", chainGiverNpc = 16013, chainStep = 21, chain = { 8905, 8922, 8921, 8924, 8925, 8928, 8977, 8926, 8929, 8945, 8946, 8947, 8948, 8949, 8950, 9015, 8951, 8960, 8961, 8962 } }, Horde = { chainStart = 8913, chainStartName = "An Earnest Proposition", chainGiver = "Mokvar", chainGiverNpc = 16012, chainStep = 21, chain = { 8913, 8923, 8921, 8924, 8925, 8928, 8978, 8927, 8930, 8945, 8946, 8947, 8948, 8949, 8950, 9015, 8957, 9032, 8961, 8962 } } }, objective = "Use the Brazier of Beckoning to summon forth the spirit of Mor Grayhoof and slay him. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning." },
