    { id = 7761, name = "Blackhand's Command", level = 60, minLevel = 55, xp = 6600, startsFrom = "Blackhand's Command", startsFromId = 18987, turnIn = "Drakkisath's Brand", turnInInside = "UBRS", shareable = false, droppers = { { name = "Scarshield Quartermaster", npc = 9046 } }, objective = "That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command.\n\nThe letter indicates that General Drakkisath guards the brand. Perhaps you should investigate." },
    { id = 6602, name = "Blood of the Black Dragon Champion", side = "Horde", level = 60, minLevel = 55, xp = 9950, giver = "Rexxar", chainStart = 4903, chainStartName = "Warlord's Command", giverNpc = 10182, chainGiver = "Warlord Goretooth", chainGiverNpc = 9077, turnIn = "Rexxar", turnInNpc = 10182, chainStep = 12, shareable = true, loot = { { item = 16663, name = "Blood of the Black Dragon Champion", from = { { name = "General Drakkisath" } } } }, rewards = { 16309 }, chain = { 4903, 4941, 4974, 6566, 6567, 6568, 6569, 6570, 6582, 6585, 6601 }, objective = "Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar." },
    { id = 4974, name = "For The Horde!", side = "Horde", level = 60, minLevel = 55, xp = 9950, money = 27000, giver = "Thrall", chainStart = 4903, chainStartName = "Warlord's Command", giverNpc = 4949, chainGiver = "Warlord Goretooth", chainGiverNpc = 9077, turnIn = "Thrall", turnInNpc = 4949, chainStep = 3, shareable = true, loot = { { item = 12630, name = "Head of Rend Blackhand", from = { { name = "Warchief Rend Blackhand" } } } }, choice = { 13966, 13968, 13965 }, chain = { 4903, 4941 }, objective = "Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar." },
    { id = 5102, name = "General Drakkisath's Demise", side = "Alliance", level = 60, minLevel = 55, xp = 27398, money = 27000, giver = "Marshal Maxwell", chainStart = 5089, chainStartName = "General Drakkisath's Command", giverNpc = 9560, chainStartItem = "General Drakkisath's Command", chainStartItemId = 12780, turnIn = "Marshal Maxwell", turnInNpc = 9560, chainStep = 2, shareable = true, chainDroppers = { { name = "Overlord Wyrmthalak", inside = "LBRS" } }, kills = { { name = "General Drakkisath" } }, choice = { 13966, 13968, 13965 }, chain = { 5089 }, objective = "Travel to Blackrock Spire and destroy General Drakkisath. Return to Marshal Maxwell when the job is done." },
    { id = 5127, name = "The Demon Forge", profession = "Blacksmithing", level = 60, minLevel = 55, xp = 8300, giver = "Lorax", chainStart = 5126, chainStartName = "Lorax's Tale", giverNpc = 10918, chainGiver = "Lorax", chainGiverNpc = 10918, turnIn = "Lorax", turnInNpc = 10918, chainStep = 2, shareable = false, loot = { { item = 12847, name = "Soul Stained Pike", from = { { name = "Goraluk Anvilcrack" } } }, { item = 12806, name = "Unforged Rune Covered Breastplate", from = { { name = "Unforged Runic Breastplate" } } } }, rewards = { 12696, 9224, 12849 }, chain = { 5126 }, objective = "Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained.\n\nYou must also find the Unforged Rune Covered Breastplate.\n\nReturn both the Soul Stained Pike and the Unforged Rune Covered Breastplate to Lorax in Winterspring." },
