    { id = 7482, name = "Elven Legends", side = "Alliance", level = 60, minLevel = 54, xp = 19700, money = 18000, giver = "Scholar Runethorn", giverNpc = 14374, turnIn = "Scholar Runethorn", turnInNpc = 14374, shareable = true, objective = "Search Dire Maul for Telmius Dreamseeker. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find." },
    { id = 7461, name = "The Madness Within", level = 60, minLevel = 56, xp = 9950, giver = "Shen'dralar Ancient", giverInside = "DM_WEST", turnIn = "Shen'dralar Ancient", turnInInside = "DM_WEST", shareable = true, kills = { { name = "Immol'thar" }, { name = "Prince Tortheldrin" } }, objective = "You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.\n\nEnter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.\n\nReturn to the Shen'dralar Ancient in the courtyard should you complete this quest." },
    { id = 1318, name = "Unfinished Gordok Business", level = 60, minLevel = 56, xp = 8300, giver = "Captain Kromcrush", giverInside = "DM_NORTH", shareable = false, loot = { { item = 18336, name = "Gauntlet of Gordok Might", from = { { name = "The Prince's Chest" } } } }, choice = { 18366, 18367, 18368, 18369 }, alt = { 7703 }, objective = "Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.\n\nAccording to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings." },
