ns.Data:RegisterQuests("SCHOLOMANCE", {  -- Scholomance
    { id = 5341, name = "Barov Family Fortune", side = "Horde", level = 60, minLevel = 52, xp = 6600, money = 18000, giver = "Alexi Barov", giverNpc = 11022, turnIn = "Alexi Barov", turnInNpc = 11022, shareable = true, loot = { { item = 13471, name = "The Deed to Brill", from = { { name = "The Deed to Brill" } } }, { item = 13448, name = "The Deed to Caer Darrow", from = { { name = "The Deed to Caer Darrow" } } }, { item = 13450, name = "The Deed to Southshore", from = { { name = "The Deed to Southshore" } } }, { item = 13451, name = "The Deed to Tarren Mill", from = { { name = "The Deed to Tarren Mill" } } } }, objective = "Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task." },
