    { id = 5582, name = "Healthy Dragon Scale", level = 58, minLevel = 55, xp = 0, startsFrom = "Healthy Dragon Scale", startsFromId = 13920, chainStart = 5529, chainStartName = "Plagued Hatchlings", chainGiver = "Betina Bigglezink", chainGiverNpc = 11035, turnIn = "Betina Bigglezink", turnInNpc = 11035, chainStep = 2, shareable = false, droppers = { { name = "Plagued Hatchling" } }, chain = { 5529 }, objective = "Bring the Healthy Dragon Scale to Betina Bigglezink at the Light's Hope Chapel in Eastern Plaguelands." },
    { id = 5529, name = "Plagued Hatchlings", level = 58, minLevel = 55, xp = 6200, money = 9000, giver = "Betina Bigglezink", giverNpc = 11035, turnIn = "Betina Bigglezink", turnInNpc = 11035, shareable = true, kills = { { name = "Plagued Hatchling" } }, objective = "Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel." },
    { id = 5382, name = "Doctor Theolen Krastinov, the Butcher", level = 60, minLevel = 55, xp = 16014, giver = "Eva Sarkhoff", giverNpc = 11216, turnIn = "Eva Sarkhoff", turnInNpc = 11216, shareable = true, kills = { { name = "Doctor Theolen Krastinov" } }, named = { { name = "Lucien Sarkhoff", npc = 11217 } }, objective = "Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete." },
    { id = 5384, name = "Kirtonos the Herald", level = 60, minLevel = 55, xp = 20094, giver = "Eva Sarkhoff", chainStart = 5382, chainStartName = "Doctor Theolen Krastinov, the Butcher", giverNpc = 11216, chainGiver = "Eva Sarkhoff", chainGiverNpc = 11216, turnIn = "Eva Sarkhoff", turnInNpc = 11216, chainStep = 3, shareable = false, kills = { { name = "Kirtonos the Herald" } }, choice = { 15805, 15806 }, rewards = { 13544 }, chain = { 5382, 5515 }, objective = "Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.\n\nFight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff." },
    { id = 5515, name = "Krastinov's Bag of Horrors", level = 60, minLevel = 55, xp = 16014, giver = "Eva Sarkhoff", chainStart = 5382, chainStartName = "Doctor Theolen Krastinov, the Butcher", giverNpc = 11216, chainGiver = "Eva Sarkhoff", chainGiverNpc = 11216, turnIn = "Eva Sarkhoff", turnInNpc = 11216, chainStep = 2, shareable = true, loot = { { item = 13725, name = "Krastinov's Bag of Horrors", from = { { name = "Jandice Barov" } } } }, chain = { 5382 }, objective = "Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff." },
